# Looking for patterns - check if there are natural grid divisions
# Check for full rows/cols of single color
def is_full_line_like(row, color):
    return all(c == color for c in row if c != 0)  # Ignore zeros

def is_full_line_like_col(col_idx, color):
    return all(input_grid[r][col_idx] == color for r in range(20) if input_grid[r][col_idx] != 0)

# Check rows
print("Single-color rows:")
for r in range(20):
    colors = [c for c in input_grid[r] if c != 0]
    if len(set(colors)) == 1:
        print(f"  Row {r}: {input_grid[r]}")

print("\nSingle-color columns:")
for c in range(20):
    colors = [input_grid[r][c] for r in range(20) if input_grid[r][c] != 0]
    if len(set(colors)) == 1:
        print(f"  Col {c}: {[input_grid[r][c] for r in range(20)]}")

# Look at the structure around the zeros
print("\nRegion around zeros (rows 12-15, cols 11-14):")
for r in range(12, 15):
    row_str = "".join(str(input_grid[r][c]) for c in range(11, 15))
    print(f"  Row {r}: {row_str}")

# Check if there's a 4x4 division (20/4=5)
print("\n=== Checking 4x4 block structure (5x5 blocks) ===")
for br in range(4):
    for bc in range(4):
        block = [[input_grid[br*5+i][bc*5+j] for j in range(5)] for i in range(5)]
        unique = set(c for row in block for c in row if c != 0)
        zero_count = sum(1 for row in block for c in row if c == 0)
        print(f"  Block ({br},{bc}): {5*5} cells, {len(unique)} unique non-0 colors, {zero_count} zeros")

# Verify the diagonal structure thoroughly
print("=== Verifying main diagonals (top-left to bottom-right) ===")
main_diags = []
for d in range(5):
    diag_cells = []
    for r in range(20):
        c = r - d
        if 0 <= c < 20:
            diag_cells.append(input_grid[r][c])
    if d in range(5):
        main_diags.append(diag_cells)
        print(f"d={d}: {diag_cells}")

print("\nComparing main diags:")
for d in range(1, 5):
    if main_diags[0] == main_diags[d]:
        print(f"  Main diag {d} == Main diag 0: YES")
    else:
        print(f"  Main diag {d} != Main diag 0")

print("\n=== Verifying anti-diagonals (top-right to bottom-left) ===")
# Anti-diagonals: c + r = constant, but we have 20x20 so let's trace them
# An anti-diagonal starts from c=k and goes to c=k-4 until c=0 or r=19
anti_diags = []
for d in range(5):
    diag_cells = []
    for r in range(20):
        c = 19 - r + d  # This gives us anti-diagonals
        if 0 <= c < 20:
            diag_cells.append(input_grid[r][c])
    if d in range(5):
        anti_diags.append(diag_cells)
        print(f"d={d}: {diag_cells}")

print("\nComparing anti-diags:")
for d in range(1, 5):
    if anti_diags[0] == anti_diags[d]:
        print(f"  Anti-diag {d} == Anti-diag 0: YES")
    else:
        print(f"  Anti-diag {d} != Anti-diag 0")

# Actually, let me think about this differently
# With 20x20 grid and 5 diagonal patterns, maybe it's a kaleidoscope/tunnel effect
# Let's check if the pattern repeats every 5 positions
print("\n=== Checking 5-position periodicity ===")
# Check if grid[r][c] == grid[r%5][c%5] with some pattern
print("Top-left 5x5:")
top_left = [[input_grid[r][c] for c in range(5)] for r in range(5)]
for row in top_left:
    print(row)

print("\nCompare with rest of 1st row (positions where r=0 and c>=5):")
for r in range(5):
    for c_start in range(5, 20, 5):
        chunk = input_grid[r][c_start:c_start+5]
        print(f"Row {r}, cols {c_start}-{c_start+4}: {chunk}")
